<div class="admin-title"><div><span class="eyebrow">CARE FOR THE CONVERSATION</span><h1><?= e($title) ?></h1><p><?= t('Review pending comments and reports. Published content is managed in the content library.') ?></p></div></div><?php foreach (['comments','reports'] as $entity): $rows=$a->db->all('SELECT c.*,u.username FROM cy_'.$entity.' c JOIN cy_users u ON u.id=c.user_id WHERE c.status=? ORDER BY c.id ASC LIMIT 100',['pending']); ?><section class="panel section"><div class="section-heading"><h2><?= t($entity) ?></h2><span class="pill"><?= count($rows) ?></span></div><?php foreach ($rows as $row): ?><article class="moderation-item"><div class="row between"><strong>@<?= e($row['username']) ?></strong><a href="<?= e(url('article',['id'=>$row['content_id']])) ?>" class="text-link"><?= t('Open content') ?> #<?= (int)$row['content_id'] ?></a></div><p><?= nl2br(e($row['body']??$row['reason'])) ?></p><small><?= dt((int)$row['created_at'],'Y.m.d H:i') ?></small><?= form_start('admin_moderate','','row') . hidden('entity',$entity) . hidden('id',$row['id']) ?><button class="btn small" name="status" value="<?= $entity==='comments'?'approved':'resolved' ?>"><?= icon('check') ?><?= t($entity==='comments'?'Approve':'Resolve') ?></button><button class="btn secondary small" name="status" value="<?= $entity==='comments'?'rejected':'dismissed' ?>"><?= t($entity==='comments'?'Reject':'Dismiss') ?></button></form></article><?php endforeach ?><?php if (!$rows) {empty_state('Nothing is waiting for review.','shield');} ?><p class="hint"><?= t('The oldest 100 pending items are shown first. Refresh after processing to see more.') ?></p></section><?php endforeach ?>
